from pathlib import Path
import struct, subprocess, os, random, itertools, sys
base=bytearray(Path('/workspace/repo-vul/src-vul/harfbuzz/test/shaping/data/in-house/fonts/TestDFONT.dfont').read_bytes())
dataOff,mapOff,dataLen,mapLen=struct.unpack('>IIII', base[:16])
tl=mapOff+struct.unpack('>H', base[mapOff+24:mapOff+26])[0]
res0=tl+struct.unpack('>H', base[tl+2+6:tl+2+8])[0]
print('len',len(base),'dataOff',dataOff,'mapOff',mapOff,'dataLen',dataLen,'tl',tl,'res0',res0)
# generate targeted mutations
cands=[]
def add(name,b):
 p=Path('/tmp/cands')/name; p.parent.mkdir(exist_ok=True); p.write_bytes(b); cands.append(p)
# dataLen variants with valid font
for dl in [0,1,2,3,4,8,12,16,32,64,128,255,256,512,1024,2488,2489,2492,3000,3170,3171,3249,3250,0xffffffff,0x80000000,0x10000000]:
 b=bytearray(base); b[8:12]=dl.to_bytes(4,'big'); add(f'dl_{dl:x}',b)
# resource offset variants around/end; set LArray length and maybe sfnt tag at target
for off in [0,1,2,3,4,8,12,16,32,64,128,2480,2484,2488,2492,3000,3160,3166,3170,3171,3180,3300,3400,3490,0xfffffe & 0xffffff, 0xffffff]:
 b=bytearray(base); b[res0+5:res0+8]=off.to_bytes(3,'big'); add(f'off_{off:x}',b)
# combine small dataLen and offsets to map area, put minimal LArray len maybe at map offsets? no
for dl in [0,1,4,16,64,128,1024,2488]:
 for off in [2488,2492,3000,3170,3180,3300]:
  b=bytearray(base); b[8:12]=dl.to_bytes(4,'big'); b[res0+5:res0+8]=off.to_bytes(3,'big'); add(f'combo_{dl:x}_{off:x}',b)
# truncate file lengths with original fields
for L in [16,32,64,128,255,256,300,512,1024,2048,2748,3426,3454,3472,3484,3500,3504]:
 add(f'trunc_{L}', bytearray(base[:L]))
for p in cands:
 r=subprocess.run(['/tmp/hbshape_full_vul',str(p)], stdout=subprocess.PIPE, stderr=subprocess.PIPE, timeout=3)
 if r.returncode!=0:
  print('CRASH?',p,r.returncode)
  print(r.stderr.decode('latin1')[:2000])
  sys.exit(0)
print('no crash',len(cands))
